import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;class PublicExamplesTest{static String capture(Runnable action){PrintStream previous=System.out;ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(PrintStream out=new PrintStream(bytes,true,StandardCharsets.UTF_8)){System.setOut(out);action.run();}finally{System.setOut(previous);}return bytes.toString(StandardCharsets.UTF_8).replace("\r\n","\n");}@Test void publishedSelection(){Object a=TaskBinding.book(1,new String[]{"Ann","Bob"},"P",2020),b=TaskBinding.book(2,new String[]{"Ann"},"Q",2021);Object[]input=TaskBinding.array(a,b);assertValues(new Object[]{a,b},select(input,()->TaskBinding.author(input,"Ann")));assertValues(new Object[0],select(input,()->TaskBinding.author(input,"Unknown")));assertValues(new Object[]{b},select(input,()->TaskBinding.after(input,2020)));}static void assertValues(Object[]expected,Object[]actual){assertNotNull(actual,"подборка");assertEquals(java.util.Arrays.stream(expected).map(TaskBinding::value).toList(),java.util.Arrays.stream(actual).map(TaskBinding::value).toList(),"значения, порядок и кратность подборки; identity результата свободна");}static Object[] select(Object[]input,java.util.function.Supplier<Object[]>action){Object[]before=input.clone();var states=java.util.Arrays.stream(before).map(TaskBinding::value).toList();Object[]result=action.get();assertEquals(before.length,input.length);for(int i=0;i<before.length;i++)assertSame(before[i],input[i],"селектор изменил ячейку переданного typed массива, index="+i);assertEquals(states,java.util.Arrays.stream(input).map(TaskBinding::value).toList(),"селектор изменил поля исходных объектов");return result;}}
